class Solution:
    def minOperations(self, nums: List[int]) -> int:
        from functools import reduce
        from operator import and_
        a = reduce(and_, nums)
        return 0 if all(x == a for x in nums) else 1

c.cpp:
class Solution {
public:
    int minOperations(vector<int>& nums) {
        int a = nums[0];
        for (int x : nums) a &= x;
        for (int x : nums) if (x != a) return 1;
        return 0;
    }
};

